#define LuaGetArgument_Font(L, i)           (*(Font *)luaL_checkudata(L, i, "Font"))
#define LuaGetArgument_Mesh(L, i)           (*(Mesh *)luaL_checkudata(L, i, "Mesh"))
#define LuaGetArgument_Shader(L, i)         (*(Shader *)luaL_checkudata(L, i, "Shader"))
