    lua_getfield(L, index, "y"); result.y = (float)luaL_checknumber(L, -1);
    lua_getfield(L, index, "width"); result.width = (float)luaL_checknumber(L, -1);
    lua_getfield(L, index, "height"); result.height = (float)luaL_checknumber(L, -1);
