static void LuaPush_Matrix(lua_State *L, Matrix matrix)
{
    static const char *names[16] = {
        "m0","m4","m8","m12","m1","m5","m9","m13","m2","m6","m10","m14","m3","m7","m11","m15"
    };
    float *ptr = &matrix.m0;
    lua_createtable(L, 0, 16);
    for (int i = 0; i < 16; i++)
    {
        LuaPush_float(L, ptr[i]);
        lua_setfield(L, -2, names[i]);
    }
}

